/**
 * The behaviour recipe engine (rich-behaviours brief, docs/ark/behaviour-recipes.md). Visual only:
 * the server's ecology decides every meal, birth and death.
 *
 * - Each species' recipes come from its stored text (`recipes.json`, generated by
 *   `scripts/ark-behaviour-recipes.mts`, with the phrase behind every recipe in
 *   `data/ark/behaviour-recipes.json`); the recipes are templates of building blocks
 *   (`recipe-templates.ts`, `behaviour-blocks.ts`).
 * - The schedule (`behaviour-schedule.ts`) asks `recipeIntent` for a slot's goal (a perch by the
 *   water, the water's edge, bare ground, its nest…), and `episodePose` lays the recipe's episode over
 *   its pose: an episode starts from the schedule's pose and blends back into it, so where a slot ends
 *   never changes.
 * - Pairs (rivals, a male and a female, two of a group) meet in windows of world time seeded by the
 *   pair, so both run one timeline; flocks (murmurations) by their leader.
 * - Deterministic and shared: every choice is seeded by ids, slots and the time. The same function
 *   runs near and far (positions and attitudes never jump between levels); near the camera the scene
 *   also draws what an episode carries, splashes, dirt and marks (`recipe-scene.ts`).
 *
 * Behaviour-only catches are ambient creatures only (decorative fish, insects, worms, shellfish): never a
 * catalogue animal, which only disappears through a server meal event.
 */

import table from "@/ark-scene/recipes.json";
import {BLOCKS, type BlockDef} from "@/ark-scene/behaviour-blocks";
import {AFTER_BLOCKS, ENTRY_BLOCKS, EXIT_BLOCKS, TEMPLATES, type AfterStyle, type CarryAt, type EntryStyle, type ExitStyle, type Posture, type PreyKind, type Target, type Template, type TemplateStep} from "@/ark-scene/recipe-templates";
import {bodyLengthsPerSecond, type ArkBehaviourProfile} from "@/ark-scene/behaviour-profile";
import type {ArkBeat, HoursAt, ScheduleAnimal, ScheduleWorld, Spot, Trip, TripMode, TripPose} from "@/ark-scene/behaviour-schedule";
import type {AttachPoint, AttachTag} from "@/ark-scene/world-sampler";
import {hashString} from "@/ark-scene/world";

// MARK: Species data

export type SexSystem = "separate" | "workers" | "hermaphrodite" | "changes" | "parthenogenetic";
export type SpeciesRecipes = {
    slug: string;
    recipes: Array<{id: string; weight: number}>;
    sex: {system: SexSystem; maleShare: number; bigger: "male" | "female" | null; ratio: number; duller: "male" | "female" | null};
    /** Months (1–12) of its mating and nesting seasons; empty: none stored (all year, less often). */
    mating: number[];
    nesting: number[];
    nest: {kind: string; materials: string[]} | null;
    entry: EntryStyle;
    exit: ExitStyle;
    after: AfterStyle;
    posture: Posture | null;
    hovers: boolean;
    defaulted: boolean;
    /** Its recipe ids, for a quick "has it" (posing runs often). */
    has: ReadonlySet<string>;
};

const SYSTEMS: Record<string, SexSystem> = {s: "separate", w: "workers", h: "hermaphrodite", c: "changes", p: "parthenogenetic"};
const MONTH_LETTERS = "abcdefghijkl";
const ROWS = (table as {species: Record<string, string>}).species;
const decoded = new Map<string, SpeciesRecipes>();

export function decodeRecipeRow(slug: string, row: string): SpeciesRecipes {
    const [recipes = "", sex = "", mating = "", nesting = "", nest = "", cross = "", posture = "", flags = ""] = row.split("|");
    const [system = "s", share = "50", bigger = "-", ratio = "100", duller = "-"] = sex.split(":");
    const months = (s: string) => s.split("").map((c) => MONTH_LETTERS.indexOf(c) + 1).filter((m) => m > 0);
    const [nestKind, nestMaterials] = nest.split(":");
    const [entry = "wade", exit = "walk", after = "shake"] = cross.split(":");
    return {
        slug,
        recipes: recipes
            ? recipes.split(",").map((r) => {
                  const [id, w] = r.split(".");
                  return {id, weight: Number(w ?? 5) / 9};
              })
            : [],
        sex: {system: SYSTEMS[system] ?? "separate", maleShare: Number(share) / 100, bigger: bigger === "m" ? "male" : bigger === "f" ? "female" : null, ratio: Number(ratio) / 100, duller: duller === "m" ? "male" : duller === "f" ? "female" : null},
        mating: months(mating),
        nesting: months(nesting),
        nest: nestKind ? {kind: nestKind, materials: nestMaterials ? nestMaterials.split("+") : []} : null,
        entry: (entry as EntryStyle) || "wade",
        exit: (exit as ExitStyle) || "walk",
        after: (after as AfterStyle) || "shake",
        posture: (posture as Posture) || null,
        hovers: flags.includes("h"),
        defaulted: flags.includes("d"),
        has: new Set(recipes ? recipes.split(",").map((r) => r.split(".")[0]) : [])
    };
}

const NONE: Omit<SpeciesRecipes, "slug"> = {recipes: [], sex: {system: "separate", maleShare: 0.5, bigger: null, ratio: 1, duller: null}, mating: [], nesting: [], nest: null, entry: "wade", exit: "walk", after: "shake", posture: null, hovers: false, defaulted: true, has: new Set()};

export function speciesRecipes(slug: string): SpeciesRecipes {
    const hit = decoded.get(slug);
    if (hit) return hit;
    const row = ROWS[slug];
    const out = row ? decodeRecipeRow(slug, row) : {slug, ...NONE};
    decoded.set(slug, out);
    return out;
}

export function hasRecipes(slug: string): boolean {
    return slug in ROWS;
}

// MARK: Seeded sex

export type ArkSex = "male" | "female" | null;
export type SexLook = {sex: ArkSex; /** Drawn length factor (the species' mean stays the same). */ scale: number; /** Colour: 1 as drawn, less for the duller sex. */ saturation: number; value: number};

function unit(seed: string): number {
    return (hashString(seed) % 100_003) / 100_003;
}

/** Its seeded sex (the stored ratio; none for a hermaphrodite) and how that shows (size, a duller coat or plumage), from its id. */
export function sexLook(id: string, slug: string): SexLook {
    const s = speciesRecipes(slug).sex;
    if (s.system === "hermaphrodite") return {sex: null, scale: 1, saturation: 1, value: 1};
    const sex: ArkSex = unit(`${id}#sex`) < s.maleShare ? "male" : "female";
    const half = Math.sqrt(Math.max(s.ratio, 1));
    const scale = !s.bigger ? 1 : s.bigger === sex ? half : 1 / half;
    const dull = s.duller === sex;
    return {sex, scale, saturation: dull ? 0.72 : 1, value: dull ? 0.94 : 1};
}

// MARK: Seasons and hours

function monthAt(epochSeconds: number): number {
    return new Date(epochSeconds * 1000).getUTCMonth() + 1;
}

/** How much a season-bound template runs now: in season 1; out of it 0; no season stored, a little all year. */
export function seasonFactor(species: SpeciesRecipes, season: Template["season"], epochSeconds: number): number {
    if (!season) return 1;
    const months = season === "mating" ? species.mating : species.nesting;
    if (!months.length) return season === "nesting" ? 0 : 0.25;
    return months.includes(monthAt(epochSeconds)) ? 1 : 0;
}

function hourOk(template: Template, hours: number): boolean {
    switch (template.hours) {
        case "day":
            return hours > 6.3 && hours < 18.2;
        case "night":
            return hours < 5.2 || hours > 19.5;
        case "dawn_dusk":
            return (hours > 5.5 && hours < 9.5) || (hours > 16 && hours < 20);
        case "dusk":
            return hours > 17.4 && hours < 18.6;
        default:
            return true;
    }
}

// MARK: The schedule's kit (passed in by the schedule, so this module imports no schedule code)

export type ScheduleKit = {
    placeNear: (world: ScheduleWorld, centre: {x: number; z: number}, length: number, tags: AttachTag[], radius: number, roll: number) => AttachPoint | null;
    spotOf: (point: AttachPoint) => Spot;
    groundSpot: (world: ScheduleWorld, x: number, z: number) => Spot;
    rangeSpot: (world: ScheduleWorld, profile: ArkBehaviourProfile, animal: ScheduleAnimal, centre: {x: number; z: number}, radius: number, random: () => number) => Spot;
    waterSpot: (world: ScheduleWorld, profile: ArkBehaviourProfile, animal: ScheduleAnimal, x: number, z: number, random: () => number) => Spot;
    roostOf: (world: ScheduleWorld, profile: ArkBehaviourProfile, animal: ScheduleAnimal) => Spot;
    tripAt: (world: ScheduleWorld, profile: ArkBehaviourProfile, animal: ScheduleAnimal, epochSeconds: number, hoursAt: HoursAt, activity?: ArkBehaviourProfile["activity"] | null) => Trip;
    basePose: (world: ScheduleWorld, trip: Trip, epochSeconds: number) => TripPose;
    flies: (profile: ArkBehaviourProfile) => boolean;
    aquatic: (profile: ArkBehaviourProfile) => boolean;
    floats: (profile: ArkBehaviourProfile) => boolean;
};

function rng(seed: number): () => number {
    let s = seed >>> 0 || 1;
    return () => {
        s ^= s << 13;
        s ^= s >>> 17;
        s ^= s << 5;
        return ((s >>> 0) % 1_000_003) / 1_000_003;
    };
}

// MARK: Goals (the schedule's hook)

export type RecipeIntent = {doing: string; to: Spot; mode: TripMode; recipe: string};
export type RecipeIntentInput = {
    world: ScheduleWorld;
    profile: ArkBehaviourProfile;
    animal: ScheduleAnimal;
    slug: string;
    slot: number;
    start: number;
    hours: number;
    /** What the schedule picked (the behaviour and its doing): a recipe stands in for these only. */
    behaviour: string;
    doing: string;
    centre: {x: number; z: number};
    radius: number;
    kit: ScheduleKit;
};

/** On unless a page or a test turns it off. */
let enabled = true;
export function setRecipesEnabled(on: boolean) {
    enabled = on;
    forgetRecipes();
}
export function recipesEnabled(): boolean {
    return enabled;
}

/** A slot's goal for a recipe, or null (then the schedule's own choice stands). Pure in (id, slot, the hour). */
export function recipeIntent(input: RecipeIntentInput): RecipeIntent | null {
    if (!enabled) return null;
    const species = speciesRecipes(input.slug);
    if (!species.recipes.length) return null;
    const random = rng(hashString(`${input.animal.id}#recipe#${input.slot}`));
    const sex = sexLook(input.animal.id, input.slug).sex;
    for (const {id, weight} of species.recipes) {
        const template = TEMPLATES[id];
        if (!template || template.kind !== "stay" || template.goal === "here") continue;
        if (!template.replaces.includes(input.behaviour) && !template.replaces.includes(input.doing)) continue;
        if (!hourOk(template, input.hours)) continue;
        if (template.sex === "male" && sex === "female") continue;
        // With the props' nests wired, it builds while its nest is growing (their stage), whatever the months say.
        const building = id === "nest_build" && nestSource ? nestSource(input.animal.id, input.start) : null;
        if (id === "nest_build" && nestSource && (!building || building.stage >= 1)) continue;
        const chance = weight * 0.7 * (building ? 1 : seasonFactor(species, template.season, input.start));
        if (random() >= chance) continue;
        const to = goalSpot(input, template, random);
        if (!to) continue;
        const flyer = input.kit.flies(input.profile);
        const raisedTo = to.y > Math.max(input.world.sampler.heightAt(to.x, to.z), 0) + 0.4;
        const mode: TripMode = input.kit.aquatic(input.profile) ? "water" : flyer && (raisedTo || template.goal === "perch_water" || template.goal === "nest") ? "air" : "ground";
        return {doing: template.doing, to, mode, recipe: id};
    }
    return null;
}

/** Open water near a point (deeper than `depth`), searched in seeded rings out to `reach`. */
function waterNear(world: ScheduleWorld, x: number, z: number, reach: number, depth: number, seed: number): {x: number; z: number; floor: number} | null {
    const turn = (seed % 360) * (Math.PI / 180);
    for (const f of [0.15, 0.3, 0.45, 0.6, 0.8, 1]) {
        const r = reach * f;
        for (let k = 0; k < 12; k++) {
            const a = turn + (k / 12) * Math.PI * 2;
            const px = x + Math.sin(a) * r;
            const pz = z + Math.cos(a) * r;
            const floor = world.sampler.heightAt(px, pz);
            if (floor < -depth) return {x: px, z: pz, floor};
        }
    }
    return null;
}

function goalSpot(input: RecipeIntentInput, template: Template, random: () => number): Spot | null {
    const {world, profile, animal, kit, centre} = input;
    const length = Math.max(animal.length, 0.05);
    const radius = Math.max(input.radius, 2);
    switch (template.goal) {
        case "perch_water": {
            // A branch, a rock, a ledge or the reeds with open water below or near it (or a bank, failing that).
            // Low ones first (a kingfisher fishes from a metre or a few over the water), then any height.
            const reach = Math.min(Math.max(length * 40, 4), 14);
            const lowest = Math.min(Math.max(length * 20, 2.5), 8);
            for (const low of [true, false]) {
                for (const tag of ["branch", "reeds", "rock_top", "cliff_ledge"] as AttachTag[]) {
                    const near = world.sampler.attachPoints(tag, {x: centre.x, z: centre.z, r: radius * 1.6}).filter((p) => !low || p.y - Math.max(world.sampler.heightAt(p.x, p.z), 0) < lowest);
                    const sorted = [...near].sort((a, b) => Math.hypot(a.x - centre.x, a.z - centre.z) - Math.hypot(b.x - centre.x, b.z - centre.z) || a.id.localeCompare(b.id));
                    for (const point of sorted.slice(0, 24)) if (waterNear(world, point.x, point.z, reach, 0.3, hashString(point.id))) return kit.spotOf(point);
                }
            }
            const edge = kit.placeNear(world, centre, length, ["water_edge"], radius * 1.6, random());
            return edge ? kit.spotOf(edge) : null;
        }
        case "perch": {
            const point = kit.placeNear(world, centre, length, ["branch", "rock_top", "cliff_ledge", "reeds"], radius * 1.3, random());
            return point ? kit.spotOf(point) : null;
        }
        case "edge": {
            const point = kit.placeNear(world, centre, length, ["water_edge"], Math.min(radius * 1.8, 40), random());
            return point ? {...kit.spotOf(point), y: Math.max(world.sampler.heightAt(point.x, point.z), 0)} : null;
        }
        case "water": {
            if (kit.aquatic(profile) || kit.floats(profile) || profile.moves.includes("swim")) {
                const water = waterNear(world, centre.x, centre.z, Math.max(radius * 1.5, 6), Math.max(length * 0.8, 0.4), hashString(`${animal.id}#w#${input.slot}`));
                if (!water) return null;
                return kit.waterSpot(world, profile, animal, water.x, water.z, random);
            }
            // A flyer that fishes from the air starts from the shore.
            const edge = kit.placeNear(world, centre, length, ["water_edge"], Math.min(radius * 1.8, 40), random());
            return edge ? kit.spotOf(edge) : null;
        }
        case "ground":
        case "bare": {
            if (kit.aquatic(profile)) return null;
            const spot = kit.rangeSpot(world, profile, animal, centre, radius * 0.8, random);
            return world.sampler.heightAt(spot.x, spot.z) > 0.02 ? spot : null;
        }
        case "bark": {
            const point = kit.placeNear(world, centre, length, ["bark"], radius * 1.4, random());
            return point ? kit.spotOf(point) : null;
        }
        case "rock": {
            const point = kit.placeNear(world, centre, length, ["rock_top"], radius * 1.4, random());
            return point ? kit.spotOf(point) : null;
        }
        case "nest":
            return nestSiteOf(world, profile, animal, input.slug, kit, input.start);
        default:
            return null;
    }
}

// MARK: Other lanes' sources (wired by the scene once those lanes are in: see docs/ark/behaviour-recipes.md)

/** A nest the props lane draws for an animal (its site and how far built it is at a world time), or null. */
export type NestSource = (animalId: string, epochSeconds: number) => {x: number; y: number; z: number; stage: number} | null;
/** Ambient fish schools near a point at a world time (the reef lane's `fishSchoolsNear`). */
export type FishSource = (pos: {x: number; y?: number; z: number}, radius: number, epochSeconds: number) => Array<{centre: {x: number; y: number; z: number}; radius: number; heading: {x: number; y: number; z: number}; speed: number; mode: string}>;
let nestSource: NestSource | null = null;
let fishSource: FishSource | null = null;

/** The props lane's nests: a builder carries its material to the props' nest for it, and builds while that nest is growing. */
export function setNestSource(source: NestSource | null) {
    nestSource = source;
    forgetRecipes();
}
/** The reef lane's ambient schools: a chase goes after the nearest school (where it will be), a plunge into it. */
export function setFishSource(source: FishSource | null) {
    fishSource = source;
    forgetRecipes();
}
export function hasNestSource(): boolean {
    return Boolean(nestSource);
}

/**
 * The adapter for the props lane (`props/nest-growth.ts`): its sites (`nestSites()`, with `sitter`) and stages
 * (`nestStage(speciesId, siteId, arkDay)`), and the Ark day at a world time. Pure, as the props' own schedule is.
 */
export function nestSourceFromProps(props: {sites: () => Array<{sitter: string | null; speciesId: string; siteId: string; position: {x: number; y: number; z: number}}>; stage: (speciesId: string, siteId: string, arkDay: number) => number; arkDayAt: (epochSeconds: number) => number}): NestSource {
    return (animalId, epochSeconds) => {
        const site = props.sites().find((s) => s.sitter === animalId);
        return site ? {...site.position, stage: props.stage(site.speciesId, site.siteId, props.arkDayAt(epochSeconds))} : null;
    };
}

// MARK: Nests

const nestSites = new Map<string, Spot | null>();

/** The year of a nesting season (the season's first month's year), so a nest site is new each season. */
function nestYear(species: SpeciesRecipes, epochSeconds: number): number {
    const date = new Date(epochSeconds * 1000);
    const first = species.nesting.length ? species.nesting[0] : 3;
    return date.getUTCMonth() + 1 >= first ? date.getUTCFullYear() : date.getUTCFullYear() - 1;
}

/**
 * Its nest site this season (deterministic per animal and season): a branch for a cup, dome or platform; a wall
 * or cliff for a mud nest; reeds or the water's edge for a floating nest; the ground (shade) for a scrape or a
 * mound; a hole in bark for a cavity. Null if it builds none.
 */
export function nestSiteOf(world: ScheduleWorld, profile: ArkBehaviourProfile, animal: ScheduleAnimal, slug: string, kit: ScheduleKit, epochSeconds: number): Spot | null {
    const props = nestSource ? nestSource(animal.id, epochSeconds) : null;
    if (props) return {x: props.x, y: props.y, z: props.z, nx: 0, ny: 1, nz: 0, point: null};
    const species = speciesRecipes(slug);
    if (!species.nest) return null;
    const key = `${animal.id}#${nestYear(species, epochSeconds)}`;
    if (nestSites.has(key)) return nestSites.get(key)!;
    const kind = species.nest.kind;
    const tags: AttachTag[] =
        kind === "mud" ? ["house_wall", "cliff_ledge", "rock_face", "branch"] : kind === "floating" || kind === "bubble" ? ["reeds", "water_edge"] : kind === "cavity" ? ["bark", "branch"] : kind === "scrape" || kind === "mound" || kind === "burrow" ? ["shade", "grass"] : kit.flies(profile) ? ["branch", "reeds", "shade"] : ["shade", "grass"];
    const roll = rng(hashString(key))();
    const point = kit.placeNear(world, animal.home, Math.max(animal.length, 0.05), tags, 12, roll);
    const spot = point ? kit.spotOf(point) : kit.aquatic(profile) ? null : kit.groundSpot(world, animal.home.x + 0.8, animal.home.z + 0.6);
    nestSites.set(key, spot);
    return spot;
}

/** Days a nest takes to build (island days). */
export const NEST_BUILD_DAYS = 5;

/**
 * How far its nest is built (0–1) at a world time: through the first `NEST_BUILD_DAYS` of its nesting season it
 * grows; it stands for the rest of the season, then is gone. For the props lane's nest-stage interface.
 */
export function nestStageAt(slug: string, epochSeconds: number): number {
    const species = speciesRecipes(slug);
    if (!species.nest || !species.nesting.length) return 0;
    const date = new Date(epochSeconds * 1000);
    const month = date.getUTCMonth() + 1;
    if (!species.nesting.includes(month)) return 0;
    // Days since the season's first day (the months run in order, wrapping the year).
    const first = species.nesting[0];
    const year = month >= first ? date.getUTCFullYear() : date.getUTCFullYear() - 1;
    const start = Date.UTC(year, first - 1, 1) / 1000;
    const days = (epochSeconds - start) / 86_400;
    return Math.min(Math.max(days / NEST_BUILD_DAYS, 0), 1);
}

// MARK: Episodes

type P = {x: number; y: number; z: number};
export type Key = {
    t0: number;
    t1: number;
    block: BlockDef;
    from: P;
    to: P;
    yaw: number;
    /** Faces this point while it holds (a rival, the water). */
    face: P | null;
    carry: {item: PreyKind | "material" | "stick" | "stone"; at: CarryAt; material?: string} | null;
    catch: {kind: PreyKind; ok: boolean; at: P} | null;
    /** An ambient school or swarm near (the prey it chases or watches). */
    prey: {kind: PreyKind; at: P} | null;
    /** Its height above the ground there, for a wade (the feet on the bottom). */
    wade: boolean;
    /** The last key: to its schedule's live pose. */
    toBase: boolean;
};

export type Episode = {
    id: string;
    recipe: string;
    t0: number;
    t1: number;
    keys: Key[];
    anchor: P;
    length: number;
    /** A pair's: the other and its role. */
    other?: string | null;
    role?: "a" | "b" | null;
};

/** What a recipe adds to the pose: the block and state now, its attitude, what it carries, splashes and marks (near only). */
export type RecipeAct = {
    episode: string;
    recipe: string;
    block: string;
    /** The named animation state (the rig player's): `ARK_RECIPE_STATES`. */
    state: string;
    /** 0–1 through the block now. */
    u: number;
    pitch: number;
    roll: number;
    /** Its pose is its own (not the water band's), under the surface too. */
    own: boolean;
    carry: Key["carry"];
    prey: Key["prey"];
    /** A catch at this step: where and whether it came off. */
    catch: Key["catch"];
    fx: {kind: NonNullable<BlockDef["fx"]>; at: P; id: string; during: boolean; when: "start" | "end" | "during"} | null;
    mark: {kind: NonNullable<BlockDef["mark"]>; at: P; id: string; from: number} | null;
    label: string;
    /** A murmuration's centre and seed (the scene draws its ambient flockmates from the same function). */
    flock?: {centre: P; seed: number; t0: number; t1: number} | null;
};

export type RecipePose = TripPose & {act?: RecipeAct | null};

/** The owner a trip was worked out for (set by the schedule: its animal, profile, clock). */
export type TripOwner = {animal: ScheduleAnimal; profile: ArkBehaviourProfile; slug: string; activity: ArkBehaviourProfile["activity"] | null | undefined; hoursAt: HoursAt};

const stayEpisodes = new WeakMap<Trip, Episode | null>();
const pairEpisodes = new Map<string, Episode | null>();

export function forgetRecipes() {
    nestSites.clear();
    pairEpisodes.clear();
}

function pace(profile: ArkBehaviourProfile, length: number): number {
    return Math.max(bodyLengthsPerSecond(profile) * Math.max(length, 0.05), 0.08);
}

/** A travel block's speed (m/s) for this animal. */
function speedOf(block: BlockDef, walk: number, height: number): number {
    switch (block.id) {
        case "run":
        case "flee":
            return walk * 2.3;
        case "clash":
            return walk * 2.1;
        case "stalk":
            return walk * 0.35;
        case "wade":
            return walk * 0.45;
        case "crawl":
            return walk * 0.6;
        case "carry":
        case "push":
            return walk * 0.8;
        case "climb":
            return walk * 0.5;
        case "swim":
            return Math.max(walk * 1.4, 0.3);
        case "fly":
            return Math.min(Math.max(walk * 4, 2.5), 14);
        case "dive_air":
        case "dive_feet":
            // Faster from higher up: a kingfisher's few metres at 6-8 m/s, a gannet's twenty-odd at 20.
            return Math.min(Math.max(4 + height * 0.9, 4), 20);
        case "dive":
            return Math.max(walk * 1.2, 0.6);
        case "surface":
            return Math.max(walk * 1.2, 0.8);
        default:
            return walk;
    }
}

/** The block a "go" step resolves to: its own way of getting there. */
function goBlock(profile: ArkBehaviourProfile, kit: ScheduleKit, world: ScheduleWorld, from: P, to: P): BlockDef {
    const flat = Math.hypot(to.x - from.x, to.z - from.z);
    const raisedTo = to.y > Math.max(world.sampler.heightAt(to.x, to.z), 0) + 0.4;
    const raisedFrom = from.y > Math.max(world.sampler.heightAt(from.x, from.z), 0) + 0.4;
    if (kit.flies(profile) && (flat > 2 || raisedTo || raisedFrom)) return BLOCKS.fly;
    if (kit.aquatic(profile) || (world.sampler.heightAt(to.x, to.z) < -0.1 && world.sampler.heightAt(from.x, from.z) < -0.1)) return BLOCKS.swim;
    if (raisedTo || raisedFrom) return BLOCKS.climb;
    return BLOCKS.walk;
}

type BuildContext = {
    world: ScheduleWorld;
    kit: ScheduleKit;
    owner: TripOwner;
    species: SpeciesRecipes;
    template: Template;
    anchor: P;
    t0: number;
    t1: number;
    seed: string;
    /** A pair: where the other starts, the role, the pair's own seed (both sides share timings). */
    pair?: {other: P; role: "a" | "b"; otherLength: number; pace: number} | null;
    hours: number;
};

/** The animal's height (m), roughly, for wading depth and heights over water. */
const heightOf = (length: number) => Math.max(length * 0.6, 0.05);

function resolveTarget(ctx: BuildContext, step: TemplateStep, block: BlockDef, pos: P, random: () => number): P | null {
    const {world, owner, anchor} = ctx;
    const length = Math.max(owner.animal.length, 0.05);
    const origin = step.near === "here" ? pos : anchor;
    const scaleUp = Math.min(Math.max(length / 0.4, 0.4), 2.2);
    const sampler = world.sampler;
    const ground = (x: number, z: number) => Math.max(sampler.heightAt(x, z), 0);
    switch (step.to) {
        case undefined:
        case "here":
            return pos;
        case "anchor":
            return anchor;
        case "up":
            return {x: pos.x, y: pos.y + (step.h ?? 1) * scaleUp, z: pos.z};
        case "prey":
        case "water":
        case "over_water": {
            // The reef lane's schools, where wired: the nearest one, where it will be when it gets there.
            if (fishSource && (step.to === "prey" || block.id === "dive_air" || block.id === "dive_feet")) {
                const school = fishSource(origin, Math.max(step.r ?? 12, 8), ctx.t0)[0];
                if (school) {
                    const lead = Math.min(Math.hypot(school.centre.x - pos.x, school.centre.z - pos.z) / Math.max(speedOf(block, pace(owner.profile, length), 0), 0.5), 6);
                    const x = school.centre.x + school.heading.x * school.speed * lead;
                    const z = school.centre.z + school.heading.z * school.speed * lead;
                    if (sampler.heightAt(x, z) < -0.25) return {x, y: step.to === "prey" ? Math.min(school.centre.y, -0.2) : -Math.max(length * 0.3, 0.06), z};
                }
            }
            // A dive goes into open water (not the edge's few centimetres); a chase deeper still.
            const depth = step.to === "prey" ? Math.max(length * 1.2, 0.5) : block.id === "dive_air" || block.id === "dive_feet" ? 0.45 : 0.25;
            const reach = Math.max(step.r ?? Math.min(Math.max(length * 40, 4), 14), 1.5);
            const water = waterNear(world, origin.x, origin.z, reach, depth, hashString(`${ctx.seed}#${Math.floor(random() * 1e6)}`));
            if (!water) return null;
            if (step.to === "over_water") return {x: water.x, y: (step.h ?? 4) * scaleUp, z: water.z};
            if (step.to === "prey") return {x: water.x, y: Math.max(water.floor + length * 0.6, -Math.max(length * 2.5, 1.2)) * (0.5 + 0.4 * random()), z: water.z};
            const under = block.id === "dive_air" || block.id === "dive_feet" ? -Math.max(length * 0.3, 0.06) : 0;
            return {x: water.x, y: under, z: water.z};
        }
        case "shallows": {
            const deepest = Math.min(Math.max(heightOf(length) * 0.45, 0.04), 0.7);
            const reach = step.r ?? Math.max(length * 6, 2.5);
            const turn = random() * Math.PI * 2;
            for (const f of [0.25, 0.5, 0.75, 1, 1.4]) {
                for (let k = 0; k < 10; k++) {
                    const a = turn + (k / 10) * Math.PI * 2;
                    const x = origin.x + Math.sin(a) * reach * f;
                    const z = origin.z + Math.cos(a) * reach * f;
                    const h = sampler.heightAt(x, z);
                    if (h < -0.02 && h > -deepest) return {x, y: h, z};
                }
            }
            return null;
        }
        case "edge": {
            const near = sampler.attachPoints("water_edge", {x: origin.x, z: origin.z, r: 18});
            if (!near.length) return null;
            const best = [...near].sort((a, b) => Math.hypot(a.x - origin.x, a.z - origin.z) - Math.hypot(b.x - origin.x, b.z - origin.z) || a.id.localeCompare(b.id))[0];
            return {x: best.x, y: ground(best.x, best.z), z: best.z};
        }
        case "ground":
        case "material": {
            const centre = step.to === "material" ? nestOrigin(ctx) ?? origin : origin;
            const reach = step.r ?? 3;
            for (let k = 0; k < 10; k++) {
                const a = random() * Math.PI * 2;
                const r = reach * (0.35 + 0.65 * Math.sqrt(random()));
                const x = centre.x + Math.sin(a) * r;
                const z = centre.z + Math.cos(a) * r;
                if (sampler.heightAt(x, z) > 0.03 && world.nav.walkable(x, z)) return {x, y: ground(x, z), z};
            }
            return null;
        }
        case "air": {
            const a = random() * Math.PI * 2;
            const r = (step.r ?? 3) * (0.5 + 0.5 * random());
            return {x: origin.x + Math.sin(a) * r, y: origin.y + (random() - 0.3) * 1.2, z: origin.z + Math.cos(a) * r};
        }
        case "nest": {
            const nest = nestOrigin(ctx);
            return nest ?? null;
        }
        case "beach": {
            const reach = step.r ?? 6;
            const turn = random() * Math.PI * 2;
            for (let k = 0; k < 16; k++) {
                const a = turn + (k / 16) * Math.PI * 2;
                const x = origin.x + Math.sin(a) * reach;
                const z = origin.z + Math.cos(a) * reach;
                const h = sampler.heightAt(x, z);
                if (h > 0.05 && h < 1.6 && world.nav.walkable(x, z)) return {x, y: h, z};
            }
            return null;
        }
        case "meet":
        case "meet_far":
        case "meet_side":
        case "away": {
            const pair = ctx.pair;
            if (!pair) return pos;
            const own = ctx.anchor;
            const other = pair.other;
            const dx = other.x - own.x;
            const dz = other.z - own.z;
            const d = Math.hypot(dx, dz) || 1;
            const ux = dx / d;
            const uz = dz / d;
            const midX = (own.x + other.x) / 2;
            const midZ = (own.z + other.z) / 2;
            const both = Math.max(length, pair.otherLength);
            // Each keeps to its own side of the middle (u points from it to the other), so the two meet head-on; the
            // parallel walk goes the same way for both (role "b" turns its own perpendicular round), a body width apart.
            if (step.to === "away") {
                const x = pos.x - ux * both * 5;
                const z = pos.z - uz * both * 5;
                return {x, y: ground(x, z), z};
            }
            if (step.to === "meet_side") {
                const along = pair.role === "a" ? 1 : -1;
                const x = midX + uz * along * both * 4 - ux * both * 0.6;
                const z = midZ - ux * along * both * 4 - uz * both * 0.6;
                return {x, y: ground(x, z), z};
            }
            const gap = step.to === "meet" ? both * 0.42 : both * 2.4;
            const x = midX - ux * gap;
            const z = midZ - uz * gap;
            return {x, y: ground(x, z), z};
        }
        default:
            return pos;
    }
}

function nestOrigin(ctx: BuildContext): P | null {
    const spot = nestSiteOf(ctx.world, ctx.owner.profile, ctx.owner.animal, ctx.owner.slug, ctx.kit, ctx.t0);
    return spot ? {x: spot.x, y: spot.y, z: spot.z} : null;
}

/** The sun's bearing (yaw) at an hour: east in the morning, south at noon, west in the evening. */
function sunYaw(hours: number): number {
    return Math.PI / 2 - ((hours - 6) / 12) * Math.PI;
}

/** An episode's keys: the template's steps (then its loop while time allows, then its tail), each placed in the world from where the last left it. */
function buildEpisode(ctx: BuildContext): Episode | null {
    const {owner, template, species, world, kit} = ctx;
    const length = Math.max(owner.animal.length, 0.05);
    const random = rng(hashString(ctx.seed));
    // A pair's timings come from the pair (both sides draw the same lengths); its targets from each side's own place.
    const timing = ctx.pair ? rng(hashString(`${ctx.seed}#timing`)) : random;
    const keys: Key[] = [];
    const walk = ctx.pair ? ctx.pair.pace : pace(owner.profile, length);
    let t = ctx.t0;
    let pos: P = ctx.anchor;
    let yaw = 0;
    let carry: Key["carry"] = null;
    let caught = false;
    const material = species.nest?.materials[0] ?? "twigs";
    const reserve = 4;
    const sequence = (steps: TemplateStep[]): boolean => {
        for (const step of steps) {
            const draw = step.s ? step.s[0] + (step.s[1] - step.s[0]) * timing() : 0;
            if (step.role && ctx.pair && step.role !== ctx.pair.role) {
                // The other role's step: this side holds for the same time (so both stay in step).
                if (draw > 0) {
                    if (t + draw > ctx.t1 - reserve) return false;
                    keys.push({t0: t, t1: t + draw, block: BLOCKS.rest, from: pos, to: pos, yaw, face: ctx.pair.other, carry, catch: null, prey: null, wade: false, toBase: false});
                    t += draw;
                }
                continue;
            }
            if (step.if === "caught" && !caught) continue;
            if (step.if === "hovers" && !species.hovers) continue;
            let block = BLOCKS[step.b];
            if (!block) continue;
            const target = block.motion === "travel" ? resolveTarget(ctx, step, block, pos, random) : pos;
            if (!target) return false;
            if (block.id === "go") block = goBlock(owner.profile, kit, world, pos, target);
            const distance = Math.hypot(target.x - pos.x, target.y - pos.y, target.z - pos.z);
            const height = Math.max(pos.y - target.y, 0);
            const travelSeconds =
                block.id === "take_off"
                    ? 0.45 + 0.1 * timing()
                    : block.id === "land"
                      ? 0.6
                      : block.id === "leap" || block.id === "dive_in" || block.id === "hop_out"
                        ? 0.5 + 0.25 * timing()
                        : // A pair's travel times come from the pair's geometry (the same for both sides) at the slower one's pace.
                          (ctx.pair ? Math.hypot(target.x - pos.x, target.z - pos.z) : distance) / speedOf(block, walk, height);
            const seconds = block.motion === "travel" ? Math.max(step.s ? Math.min(Math.max(travelSeconds, step.s[0]), step.s[1]) : travelSeconds, 0.2) : Math.max(draw, 0.3);
            if (t + seconds > ctx.t1 - reserve) return false;
            const flat = Math.hypot(target.x - pos.x, target.z - pos.z);
            if (block.motion === "travel" && flat > 0.03) yaw = Math.atan2(target.x - pos.x, target.z - pos.z);
            const face: P | null = step.face === "other" && ctx.pair ? ctx.pair.other : step.face === "water" ? waterFace(world, pos, length) : null;
            if (step.face === "sun") yaw = sunYaw(ctx.hours) + Math.PI / 2;
            if (face) yaw = Math.atan2(face.x - pos.x, face.z - pos.z);
            let thisCatch: Key["catch"] = null;
            if (step.catch) {
                caught = random() < (step.p ?? 0.5);
                thisCatch = {kind: step.catch, ok: caught, at: target};
                if (caught) carry = {item: step.catch, at: step.carry ?? defaultCarry(owner.profile)};
            }
            if (step.pick) {
                carry = {item: step.pick, at: step.carry ?? defaultCarry(owner.profile), material: step.pick === "material" ? material : undefined};
            }
            const prey: Key["prey"] = step.catch === "fish" || step.catch === "shellfish" || step.to === "prey" ? {kind: step.catch ?? "fish", at: target} : step.catch === "insect" ? {kind: "insect", at: target} : null;
            keys.push({t0: t, t1: t + seconds, block, from: pos, to: target, yaw, face, carry, catch: thisCatch, prey, wade: block.id === "wade", toBase: false});
            t += seconds;
            pos = target;
            if (step.eat || step.drop) carry = null;
        }
        return true;
    };
    let completed = sequence(template.steps);
    if (completed && template.loop !== undefined) {
        for (let n = 0; n < 8 && completed; n++) {
            caught = false;
            completed = sequence(template.steps.slice(template.loop));
        }
    }
    if (template.tail) sequence(template.tail);
    if (!keys.length) return null;
    // Back to its schedule's pose (where it began, for a stay; where its schedule has it by then, for a pair), its own way:
    // this last key goes to the live pose, so it never snaps. It ends inside the window (sped up if it must).
    const home = ctx.anchor;
    const back = goBlock(owner.profile, kit, world, pos, home);
    const wanted = Math.max(Math.hypot(home.x - pos.x, home.y - pos.y, home.z - pos.z) / speedOf(back, pace(owner.profile, length), 0), 0.6);
    const seconds = Math.min(wanted, Math.max(ctx.t1 + 2 - t, 0.6));
    keys.push({t0: t, t1: t + seconds, block: back, from: pos, to: home, yaw, face: null, carry, catch: null, prey: null, wade: false, toBase: true});
    t += seconds;
    return {id: ctx.seed, recipe: template.id, t0: ctx.t0, t1: t, keys, anchor: ctx.anchor, length, other: null, role: ctx.pair?.role ?? null};
}

function waterFace(world: ScheduleWorld, at: P, length: number): P | null {
    const water = waterNear(world, at.x, at.z, Math.min(Math.max(length * 40, 4), 14), 0.05, 7);
    return water ? {x: water.x, y: 0, z: water.z} : null;
}

function defaultCarry(profile: ArkBehaviourProfile): CarryAt {
    return profile.move === "fly" || profile.moves.includes("fly") ? "beak" : "mouth";
}

// MARK: The pose

const ease = (u: number) => u * u * (3 - 2 * u);

/** Where a key puts it at a time, and its attitude. */
function keyPose(world: ScheduleWorld, key: Key, epoch: number, length: number, previous: Key | null): {p: P; yaw: number; pitch: number; roll: number; u: number; aloft: boolean} {
    const span = Math.max(key.t1 - key.t0, 1e-3);
    const u = Math.min(Math.max((epoch - key.t0) / span, 0), 1);
    const b = key.block;
    const {from, to} = key;
    let x = from.x;
    let y = from.y;
    let z = from.z;
    if (b.motion === "travel") {
        const flat = Math.hypot(to.x - from.x, to.z - from.z);
        switch (b.curve) {
            case "plunge": {
                // Steep and gathering speed: most of the drop in the last part.
                const k = Math.pow(u, 1.6);
                x = from.x + (to.x - from.x) * Math.min(u * 1.25, 1);
                z = from.z + (to.z - from.z) * Math.min(u * 1.25, 1);
                y = from.y + (to.y - from.y) * k;
                break;
            }
            case "arc": {
                const k = ease(u);
                x = from.x + (to.x - from.x) * k;
                z = from.z + (to.z - from.z) * k;
                y = from.y + (to.y - from.y) * k + Math.min(flat * 0.25, 2.5) * 4 * u * (1 - u);
                break;
            }
            case "leap": {
                x = from.x + (to.x - from.x) * u;
                z = from.z + (to.z - from.z) * u;
                y = from.y + (to.y - from.y) * u + Math.max(length * 0.6, 0.12 + flat * 0.3) * 4 * u * (1 - u);
                break;
            }
            case "rise": {
                const k = 1 - (1 - u) * (1 - u);
                x = from.x + (to.x - from.x) * u;
                z = from.z + (to.z - from.z) * u;
                y = from.y + (to.y - from.y) * k;
                break;
            }
            case "dive": {
                const k = ease(u);
                x = from.x + (to.x - from.x) * u;
                z = from.z + (to.z - from.z) * u;
                y = from.y + (to.y - from.y) * Math.min(k * 1.6, 1);
                break;
            }
            case "ground": {
                const k = b.id === "clash" ? u * u : ease(u);
                x = from.x + (to.x - from.x) * k;
                z = from.z + (to.z - from.z) * k;
                const h = world.sampler.heightAt(x, z);
                y = key.wade ? Math.min(h, 0.02) : b.wet && h < 0 ? h : Math.max(h, 0);
                break;
            }
            default: {
                const k = ease(u);
                x = from.x + (to.x - from.x) * k;
                y = from.y + (to.y - from.y) * k;
                z = from.z + (to.z - from.z) * k;
            }
        }
    }
    let yaw = key.yaw;
    if (b.motion === "travel") {
        const dx = to.x - from.x;
        const dz = to.z - from.z;
        if (Math.hypot(dx, dz) > 0.03) yaw = Math.atan2(dx, dz);
        // A charge ends nose to nose, a flee turns its back: the key's own heading.
        if (b.id === "clash" && key.face) yaw = Math.atan2(key.face.x - from.x, key.face.z - from.z);
    }
    // Its own small motion while it holds.
    const phase = (epoch - key.t0) * (b.rate ?? 1) * Math.PI * 2;
    const wave = Math.sin(phase);
    const surge = (b.surge ?? 0) * length * (b.id === "strike" || b.id === "pull" || b.id === "swipe" ? Math.max(Math.sin(Math.min(u, 1) * Math.PI), 0) : wave);
    const sway = (b.sway ?? 0) * length * wave;
    const heave = (b.heave ?? 0) * length * (b.id === "bury" || b.id === "incubate" ? Math.min(u * 4, 1) : 0.5 + 0.5 * Math.sin(phase));
    if (b.motion === "hold") {
        x += Math.sin(yaw) * surge + Math.cos(yaw) * sway;
        z += Math.cos(yaw) * surge - Math.sin(yaw) * sway;
        y += heave;
    }
    // The attitude eases in from the last block's over its first moment.
    const blend = previous ? ease(Math.min((epoch - key.t0) / 0.3, 1)) : 1;
    const pitchNow = (b.pitch ?? 0) + (b.pitchWave ?? 0) * wave;
    const pitchBefore = previous ? previous.block.pitch ?? 0 : 0;
    const pitch = pitchBefore + (pitchNow - pitchBefore) * blend;
    const roll = ((b.roll ?? 0) + (b.rollWave ?? 0) * wave) * blend + (previous ? (previous.block.roll ?? 0) * (1 - blend) : 0);
    const ground = Math.max(world.sampler.heightAt(x, z), 0);
    return {p: {x, y, z}, yaw, pitch, roll, u, aloft: Boolean(b.aloft) && y > ground + 0.05};
}

function actOf(episode: Episode, key: Key, index: number, at: ReturnType<typeof keyPose>): RecipeAct {
    const b = key.block;
    const states = b.states;
    const fx = b.fx ? {kind: b.fx, at: b.fxAt === "end" ? key.to : b.fxAt === "during" ? at.p : key.from, id: `${episode.id}#${index}`, during: b.fxAt === "during", when: b.fxAt ?? "start"} : null;
    return {
        episode: episode.id,
        recipe: episode.recipe,
        block: b.id,
        state: states[Math.min(Math.floor(at.u * states.length), states.length - 1)],
        u: at.u,
        pitch: at.pitch,
        roll: at.roll,
        own: true,
        carry: key.carry,
        prey: key.prey,
        catch: key.catch,
        fx,
        mark: b.mark ? {kind: b.mark, at: key.from, id: `${episode.id}#${index}`, from: key.t0} : null,
        label: TEMPLATES[episode.recipe]?.label ?? episode.recipe
    };
}

/** An episode's pose at a time over its schedule pose: it starts from it and ends back in it (the last moment blends). */
function onEpisode(world: ScheduleWorld, episode: Episode, base: TripPose, epoch: number): RecipePose {
    const keys = episode.keys;
    let i = 0;
    while (i + 1 < keys.length && keys[i].t1 <= epoch) i++;
    const key = keys[i];
    const live = key.toBase ? {...key, to: {x: base.x, y: base.y, z: base.z}} : key;
    const at = keyPose(world, live, epoch, episode.length, i > 0 ? keys[i - 1] : null);
    // Into its schedule's pose over the last 0.6 s (that is where it ends).
    const out = Math.min(Math.max((epoch - (episode.t1 - 0.6)) / 0.6, 0), 1);
    const k = ease(out);
    const x = at.p.x + (base.x - at.p.x) * k;
    const y = at.p.y + (base.y - at.p.y) * k;
    const z = at.p.z + (base.z - at.p.z) * k;
    let dyaw = base.yaw - at.yaw;
    while (dyaw > Math.PI) dyaw -= Math.PI * 2;
    while (dyaw < -Math.PI) dyaw += Math.PI * 2;
    const act = actOf(episode, key, i, at);
    const moving = key.block.motion === "travel" && at.u < 1;
    return {...base, x, y, z, yaw: at.yaw + dyaw * k, moving, aloft: at.aloft && k < 0.5, beat: key.block.beat, act: {...act, pitch: act.pitch * (1 - k), roll: act.roll * (1 - k)}};
}

// MARK: Which episode a trip is in

const HERE_DOINGS = new Set(["rest", "groom", "perch", "bask", "watch", "idle"]);

function stayEpisode(world: ScheduleWorld, trip: Trip, owner: TripOwner, kit: ScheduleKit): Episode | null {
    if (stayEpisodes.has(trip)) return stayEpisodes.get(trip)!;
    const species = speciesRecipes(owner.slug);
    let episode: Episode | null = null;
    const recipe = (trip as Trip & {recipe?: string | null}).recipe ?? null;
    const anchor = {x: trip.to.x, y: trip.to.y, z: trip.to.z};
    const hours = owner.hoursAt(trip.arrive);
    if (recipe && TEMPLATES[recipe]) {
        const t0 = trip.arrive + 0.5;
        const t1 = trip.end - 2.5;
        if (t1 - t0 > 6) episode = buildEpisode({world, kit, owner, species, template: TEMPLATES[recipe], anchor, t0, t1, seed: `${owner.animal.id}#ep#${trip.slot}#${recipe}`, hours});
    } else if (HERE_DOINGS.has(trip.doing) && trip.end - trip.arrive > 14 && (!trip.stay.length || trip.stay.every((b, i, all) => i === 0 || (b.x === all[0].x && b.z === all[0].z)))) {
        // A stay where it already is: groom, stretch, call, bask in its posture, dry its wings.
        const random = rng(hashString(`${owner.animal.id}#here#${trip.slot}`));
        for (const {id, weight} of species.recipes) {
            const template = TEMPLATES[id];
            if (!template || template.kind !== "stay" || template.goal !== "here") continue;
            if (!template.replaces.includes(trip.doing) || !hourOk(template, hours)) continue;
            if (random() >= weight * 0.6 * seasonFactor(species, template.season, trip.arrive)) continue;
            const start = trip.arrive + 1 + random() * Math.max(trip.end - trip.arrive - 40, 0);
            episode = buildEpisode({world, kit, owner, species, template, anchor, t0: start, t1: Math.min(trip.end - 3, start + 60), seed: `${owner.animal.id}#here#${trip.slot}#${id}`, hours});
            if (episode) break;
        }
    }
    stayEpisodes.set(trip, episode);
    return episode;
}

// MARK: Pairs

type PairLink = {template: string; other: ScheduleAnimal; otherProfile: ArkBehaviourProfile; otherSlug: string; otherActivity: ArkBehaviourProfile["activity"] | null | undefined; role: "a" | "b"; key: string};
const links = new WeakMap<ScheduleAnimal, PairLink[]>();

/** How often a pair may meet (world seconds), in season; and the longest a pair episode can run. */
export const PAIR_PERIOD = 600;
const PAIR_MAX = 90;

export type WireInput = {animal: ScheduleAnimal; profile: ArkBehaviourProfile; slug: string; activity?: ArkBehaviourProfile["activity"] | null};

/**
 * After a snapshot: who meets whom. Rival males of a species with a contest pair off with the nearest other male
 * (within 45 m, each in one pair); a male with a courtship display with the nearest female; two of a group that
 * groom each other by rank. Deterministic from ids and homes.
 */
export function wireRecipes(animals: WireInput[]) {
    const bySpecies = new Map<string, WireInput[]>();
    for (const a of animals) {
        links.delete(a.animal);
        const list = bySpecies.get(a.slug) ?? [];
        list.push(a);
        bySpecies.set(a.slug, list);
    }
    pairEpisodes.clear();
    const link = (a: WireInput, b: WireInput, template: string) => {
        const key = a.animal.id < b.animal.id ? `${template}#${a.animal.id}#${b.animal.id}` : `${template}#${b.animal.id}#${a.animal.id}`;
        // Role "a": the male in a courtship; the dominant (then the id) in a contest.
        const aIsMale = sexLook(a.animal.id, a.slug).sex === "male";
        const roleA: "a" | "b" = TEMPLATES[template].sex === "mixed" ? (aIsMale ? "a" : "b") : (a.profile.dominance ?? 0) * 1000 + unit(`${a.animal.id}#rank`) >= (b.profile.dominance ?? 0) * 1000 + unit(`${b.animal.id}#rank`) ? "a" : "b";
        const add = (x: WireInput, y: WireInput, role: "a" | "b") => {
            const list = links.get(x.animal) ?? [];
            list.push({template, other: y.animal, otherProfile: y.profile, otherSlug: y.slug, otherActivity: y.activity, role, key});
            links.set(x.animal, list);
        };
        add(a, b, roleA);
        add(b, a, roleA === "a" ? "b" : "a");
    };
    for (const [slug, list] of Array.from(bySpecies)) {
        const species = speciesRecipes(slug);
        const pairs = species.recipes.map((r) => TEMPLATES[r.id]).filter((t): t is Template => Boolean(t && t.kind === "pair"));
        if (!pairs.length || list.length < 2) continue;
        const sorted = [...list].sort((a, b) => a.animal.id.localeCompare(b.animal.id));
        const dist = (a: WireInput, b: WireInput) => Math.hypot(a.animal.home.x - b.animal.home.x, a.animal.home.z - b.animal.home.z);
        for (const template of pairs) {
            const taken = new Set<string>();
            const pool = template.sex === "males" ? sorted.filter((a) => sexLook(a.animal.id, slug).sex === "male") : sorted;
            if (template.id === "allogroom") {
                // Neighbours in rank within one group.
                const groups = new Map<string, WireInput[]>();
                for (const a of pool) {
                    const lead = a.animal.group?.leader.id ?? a.animal.id;
                    const g = groups.get(lead) ?? [];
                    g.push(a);
                    groups.set(lead, g);
                }
                for (const g of Array.from(groups.values())) {
                    const ranked = [...g].sort((a, b) => (a.animal.group?.rank ?? 0) - (b.animal.group?.rank ?? 0) || a.animal.id.localeCompare(b.animal.id));
                    for (let k = 0; k + 1 < ranked.length; k += 2) link(ranked[k], ranked[k + 1], template.id);
                }
                continue;
            }
            for (const a of pool) {
                if (taken.has(a.animal.id)) continue;
                if (template.sex === "mixed" && sexLook(a.animal.id, slug).sex !== "male") continue;
                const candidates = pool.filter((b) => b !== a && !taken.has(b.animal.id) && (template.sex !== "mixed" || sexLook(b.animal.id, slug).sex === "female") && dist(a, b) < 45);
                if (!candidates.length) continue;
                const b = candidates.sort((m, n) => dist(a, m) - dist(a, n) || m.animal.id.localeCompare(n.animal.id))[0];
                taken.add(a.animal.id);
                taken.add(b.animal.id);
                link(a, b, template.id);
            }
        }
    }
}

export function pairLinksOf(animal: ScheduleAnimal): ReadonlyArray<Pick<PairLink, "template" | "role" | "key"> & {other: string}> {
    return (links.get(animal) ?? []).map((l) => ({template: l.template, role: l.role, key: l.key, other: l.other.id}));
}

/** A pair's meeting windows (world seconds) between two times: in season every period, out of it one in four (pure). */
export function pairWindows(animal: ScheduleAnimal, slug: string, from: number, to: number): Array<{template: string; start: number; end: number; other: string}> {
    const out: Array<{template: string; start: number; end: number; other: string}> = [];
    const species = speciesRecipes(slug);
    for (const l of links.get(animal) ?? []) {
        const template = TEMPLATES[l.template];
        for (let period = Math.floor(from / PAIR_PERIOD); period * PAIR_PERIOD < to; period++) {
            const factor = seasonFactor(species, template.season, period * PAIR_PERIOD);
            if (!factor || (factor < 1 && hashString(`${l.key}#on#${period}`) % 4 !== 0)) continue;
            const start = period * PAIR_PERIOD + (hashString(`${l.key}#${period}`) % (PAIR_PERIOD - PAIR_MAX));
            if (start + PAIR_MAX >= from && start < to) out.push({template: l.template, start, end: start + PAIR_MAX, other: l.other.id});
        }
    }
    return out.sort((a, b) => a.start - b.start);
}

/** A pair's episode for one side at a time (null: none now). Both sides work out the same window from the pair's key. */
function pairEpisode(world: ScheduleWorld, owner: TripOwner, kit: ScheduleKit, epoch: number): Episode | null {
    const list = links.get(owner.animal);
    if (!list) return null;
    for (const l of list) {
        const template = TEMPLATES[l.template];
        const species = speciesRecipes(owner.slug);
        const factor = seasonFactor(species, template.season, epoch);
        if (!factor) continue;
        // Out of a stored season, a quarter as often: one period in four.
        const period = Math.floor(epoch / PAIR_PERIOD);
        if (factor < 1 && hashString(`${l.key}#on#${period}`) % 4 !== 0) continue;
        const start = period * PAIR_PERIOD + (hashString(`${l.key}#${period}`) % (PAIR_PERIOD - PAIR_MAX));
        if (epoch < start || epoch >= start + PAIR_MAX) continue;
        const memoKey = `${l.key}#${period}#${l.role}`;
        let episode = pairEpisodes.get(memoKey);
        if (episode === undefined) {
            episode = null;
            const hours = owner.hoursAt(start);
            const own = kit.basePose(world, kit.tripAt(world, owner.profile, owner.animal, start, owner.hoursAt, owner.activity), start);
            const other = kit.basePose(world, kit.tripAt(world, l.otherProfile, l.other, start, owner.hoursAt, l.otherActivity), start);
            const ownTrip = kit.tripAt(world, owner.profile, owner.animal, start, owner.hoursAt, owner.activity);
            const otherTrip = kit.tripAt(world, l.otherProfile, l.other, start, owner.hoursAt, l.otherActivity);
            const onLand = (p: TripPose) => !p.aloft && world.sampler.heightAt(p.x, p.z) > 0.03 && p.y < Math.max(world.sampler.heightAt(p.x, p.z), 0) + 0.3;
            const awake = (t: Trip) => t.doing !== "sleep" && t.doing !== "to_roost";
            if (hourOk(template, hours) && onLand(own) && onLand(other) && awake(ownTrip) && awake(otherTrip) && Math.hypot(own.x - other.x, own.z - other.z) < 40) {
                episode = buildEpisode({
                    world,
                    kit,
                    owner,
                    species,
                    template,
                    anchor: {x: own.x, y: own.y, z: own.z},
                    t0: start,
                    t1: start + PAIR_MAX,
                    seed: `${l.key}#${period}`,
                    pair: {other: {x: other.x, y: other.y, z: other.z}, role: l.role, otherLength: l.other.length, pace: Math.min(pace(owner.profile, owner.animal.length), pace(l.otherProfile, l.other.length))},
                    hours
                });
                if (episode) episode = {...episode, other: l.other.id, role: l.role};
            }
            pairEpisodes.set(memoKey, episode);
            if (pairEpisodes.size > 400) pairEpisodes.delete(pairEpisodes.keys().next().value as string);
        }
        if (episode && epoch < episode.t1) return episode;
    }
    return null;
}

// MARK: Flocks: murmurations at dusk, V-formations in the air

/** The murmuration's window (island hours) and how many ambient flockmates fill it out near the camera. */
export const MURMURATION_HOURS: [number, number] = [17.45, 18.25];
export const MURMURATION_AMBIENT = 360;

/**
 * A point of a murmuration (pure in its centre, the time and the bird's index): a shape that stretches, turns and
 * drifts over the roost, each bird circling inside it, with density waves passing through. Catalogue birds use
 * their own index; the scene's ambient flockmates use the rest.
 */
export function murmurationPoint(centre: P, seed: number, index: number, epoch: number): {x: number; y: number; z: number} {
    const t = epoch;
    const s = (seed % 1000) / 1000;
    const cx = centre.x + 9 * Math.sin(t * 0.031 + s * 6) + 4 * Math.sin(t * 0.083 + s * 2);
    const cz = centre.z + 7 * Math.cos(t * 0.027 + s * 5) + 3 * Math.cos(t * 0.071 + s);
    const cy = centre.y + 16 + 4 * Math.sin(t * 0.05 + s * 3);
    const a = 13 + 6 * Math.sin(t * 0.07 + s);
    const b = 4.5 + 2.2 * Math.sin(t * 0.11 + 1 + s);
    const c = 8 + 5 * Math.cos(t * 0.053 + s * 4);
    const turn = 0.35 * t * 0.02 + Math.sin(t * 0.013 + s) * 1.2;
    // The bird's seeded place in a unit ball, circling about a slowly wandering axis.
    const r = rng(hashString(`m${seed}#${index}`));
    const u0 = r() * 2 - 1;
    const th = r() * Math.PI * 2;
    const rad = Math.cbrt(r());
    const q = Math.sqrt(1 - u0 * u0);
    const bx = rad * q * Math.cos(th);
    const by = rad * u0;
    const bz = rad * q * Math.sin(th);
    const spin = (0.22 + 0.12 * r()) * t;
    const rx = bx * Math.cos(spin) - bz * Math.sin(spin);
    const rz = bx * Math.sin(spin) + bz * Math.cos(spin);
    const wave = 0.18 * Math.sin(rx * 4 - t * 1.7) + 0.08 * Math.sin(rz * 6 + t * 1.1);
    const lx = (rx + wave) * a;
    const ly = by * b + 1.5 * Math.sin(rx * 3 + t * 0.9);
    const lz = rz * c;
    return {x: cx + lx * Math.cos(turn) - lz * Math.sin(turn), y: Math.max(cy + ly, centre.y + 4), z: cz + lx * Math.sin(turn) + lz * Math.cos(turn)};
}

/** Its murmuration now: its flock's roost and the time inside the window, or null. */
export function murmurationOf(world: ScheduleWorld, owner: TripOwner, kit: ScheduleKit, epoch: number): {centre: P; seed: number; t0: number; t1: number} | null {
    const species = speciesRecipes(owner.slug);
    if (!species.has.has("murmuration")) return null;
    const hours = owner.hoursAt(epoch);
    if (hours < MURMURATION_HOURS[0] || hours > MURMURATION_HOURS[1]) return null;
    const leader = owner.animal.group?.leader ?? owner.animal;
    const leaderProfile = owner.animal.group?.profile ?? owner.profile;
    const roost = kit.roostOf(world, leaderProfile, leader);
    // The window in world seconds (the hours map to the clock one to one).
    const t0 = epoch - (hours - MURMURATION_HOURS[0]) * 3600;
    const t1 = t0 + (MURMURATION_HOURS[1] - MURMURATION_HOURS[0]) * 3600;
    return {centre: {x: roost.x, y: Math.max(world.sampler.heightAt(roost.x, roost.z), 0), z: roost.z}, seed: hashString(leader.id), t0, t1};
}

function murmurationPose(world: ScheduleWorld, owner: TripOwner, kit: ScheduleKit, base: TripPose, epoch: number): RecipePose | null {
    const m = murmurationOf(world, owner, kit, epoch);
    if (!m) return null;
    const index = hashString(owner.animal.id) % 997;
    const p = murmurationPoint(m.centre, m.seed, index, epoch);
    const ahead = murmurationPoint(m.centre, m.seed, index, epoch + 0.2);
    // Up into it from where it was over the first 40 s, down to its roost over the last 40 s.
    const k = ease(Math.min(Math.min(epoch - m.t0, m.t1 - epoch) / 40, 1));
    const x = base.x + (p.x - base.x) * k;
    const y = base.y + (p.y - base.y) * k;
    const z = base.z + (p.z - base.z) * k;
    const yaw = Math.atan2(ahead.x - p.x, ahead.z - p.z);
    const climb = Math.atan2(ahead.y - p.y, Math.hypot(ahead.x - p.x, ahead.z - p.z) || 1e-3);
    return {
        ...base,
        x,
        y,
        z,
        yaw: k > 0.5 ? yaw : base.yaw,
        moving: true,
        aloft: true,
        beat: "fly",
        act: {episode: `murmuration#${m.seed}#${Math.floor(m.t0)}`, recipe: "murmuration", block: "fly", state: "fly", u: (epoch - m.t0) / (m.t1 - m.t0), pitch: -climb * k, roll: -0.4 * k * Math.sin(epoch * 0.9 + index), own: true, carry: null, prey: null, catch: null, fx: null, mark: null, label: TEMPLATES.murmuration.label, flock: m}
    };
}

/** A flock follower in the air takes its V slot behind its leader (geese, cranes), easing in and out of it. */
function formationPose(world: ScheduleWorld, owner: TripOwner, trip: Trip, base: TripPose, epoch: number, kit: ScheduleKit): RecipePose | null {
    const group = owner.animal.group;
    if (!group || !trip.shadow || !base.aloft) return null;
    const species = speciesRecipes(owner.slug);
    if (!species.has.has("v_formation")) return null;
    const lead = trip.shadow.trips.find((t) => epoch >= t.start && epoch < t.end) ?? trip.shadow.trips[trip.shadow.trips.length - 1];
    const leader = kit.basePose(world, lead, Math.min(epoch, lead.end - 0.001));
    if (!leader.aloft) return null;
    const rank = Math.max(group.rank, 1);
    const side = rank % 2 ? 1 : -1;
    const k = Math.ceil(rank / 2);
    const spacing = Math.max(owner.animal.length, 0.3) * 1.5;
    const fx = Math.sin(leader.yaw);
    const fz = Math.cos(leader.yaw);
    const tx = leader.x - fx * k * spacing * 0.95 + fz * side * k * spacing * 0.7;
    const tz = leader.z - fz * k * spacing * 0.95 - fx * side * k * spacing * 0.7;
    const ty = leader.y + k * 0.04 * spacing;
    // Into the V over 8 s after it joins, out of it over the last 8 s of the slot.
    const w = ease(Math.min(Math.max(Math.min(epoch - trip.start - 6, trip.end - epoch) / 8, 0), 1));
    return {...base, x: base.x + (tx - base.x) * w, y: base.y + (ty - base.y) * w, z: base.z + (tz - base.z) * w, yaw: base.yaw + Math.atan2(Math.sin(leader.yaw - base.yaw), Math.cos(leader.yaw - base.yaw)) * w};
}

// MARK: Land and water crossings

function crossingPose(world: ScheduleWorld, owner: TripOwner, trip: Trip, base: TripPose, epoch: number): RecipePose | null {
    if (base.beat !== "enter_water" && base.beat !== "exit_water" && base.beat !== "shake") return null;
    const species = speciesRecipes(owner.slug);
    const length = Math.max(owner.animal.length, 0.05);
    // The leg it is on (or, for the shake after climbing out, the time since it arrived).
    let t = epoch - trip.start;
    let leg = trip.legs[0];
    for (const l of trip.legs) {
        leg = l;
        if (t < l.seconds) break;
        t -= l.seconds;
    }
    const u = Math.min(Math.max(t / Math.max(leg.seconds, 1e-3), 0), 1);
    if (base.beat === "shake") {
        const block = AFTER_BLOCKS[species.after];
        if (!block || block === "shake_off") return null;
        const b = BLOCKS[block];
        return {...base, beat: b.beat, act: {episode: `after#${trip.slot}`, recipe: "crossing", block: b.id, state: b.states[0], u: 0, pitch: b.pitch ?? 0, roll: b.roll ?? 0, own: false, carry: null, prey: null, catch: null, fx: null, mark: null, label: b.label}};
    }
    const blockId = base.beat === "enter_water" ? ENTRY_BLOCKS[species.entry] : EXIT_BLOCKS[species.exit];
    const b = BLOCKS[blockId];
    if (!b || blockId === "walk" || blockId === "wade") return null;
    let y = base.y;
    if (b.curve === "leap") y += Math.max(length * 0.5, 0.1) * 4 * u * (1 - u);
    if (b.id === "slide_in") y = Math.max(base.y - length * 0.15, Math.min(world.sampler.heightAt(base.x, base.z), base.y));
    if (b.id === "haul_out") y += (b.heave ?? 0) * length * Math.max(Math.sin(u * Math.PI * 6), 0);
    return {
        ...base,
        y,
        beat: b.beat,
        act: {episode: `cross#${trip.slot}`, recipe: "crossing", block: b.id, state: b.states[0], u, pitch: b.pitch ?? 0, roll: 0, own: false, carry: null, prey: null, catch: null, fx: b.fx ? {kind: b.fx, at: {x: base.x, y: 0, z: base.z}, id: `cross#${owner.animal.id}#${trip.slot}#${b.id}`, during: b.fxAt === "during", when: b.fxAt ?? "start"} : null, mark: null, label: b.label}
    };
}

// MARK: The schedule's other hook

/**
 * Its pose with its recipe laid over: a pair's meeting, its flock's murmuration, its V, a stay's episode, a
 * crossing's style, its sleeping posture. Pure in (the trip, the time): the same near and far.
 */
export function episodePose(world: ScheduleWorld, trip: Trip, base: TripPose, epoch: number, kit: ScheduleKit): RecipePose {
    if (!enabled) return base;
    const owner = (trip as Trip & {owner?: TripOwner | null}).owner;
    if (!owner) return base;
    const murmuring = murmurationPose(world, owner, kit, base, epoch);
    if (murmuring) return murmuring;
    if (trip.doing === "sleep") return postureOf(owner, base);
    const pair = pairEpisode(world, owner, kit, epoch);
    if (pair) return onEpisode(world, pair, base, epoch);
    if (trip.shadow) return formationPose(world, owner, trip, base, epoch, kit) ?? base;
    if (epoch >= trip.arrive) {
        const stay = stayEpisode(world, trip, owner, kit);
        if (stay && epoch >= stay.t0 && epoch < stay.t1) return onEpisode(world, stay, base, epoch);
    }
    return crossingPose(world, owner, trip, base, epoch) ?? base;
}

const postureActs = new Map<string, RecipeAct>();

/** Its sleeping posture (one shared act per posture and attitude: sleeping animals are posed often). */
function postureOf(owner: TripOwner, base: TripPose): RecipePose {
    const posture = speciesRecipes(owner.slug).posture;
    if (!posture) return base;
    const roll = posture === "hang" || (posture === "float" && base.y <= 0.02) ? Math.PI : 0;
    const key = `${posture}#${roll}`;
    let act = postureActs.get(key);
    if (!act) postureActs.set(key, (act = Object.freeze({episode: "sleep", recipe: "posture", block: "sleep_pose", state: `sleep_${posture}`, u: 0, pitch: posture === "curl" ? 0.15 : 0, roll, own: false, carry: null, prey: null, catch: null, fx: null, mark: null, label: `sleeps (${posture.replace("_", " ")})`}) as RecipeAct));
    return {...base, act};
}

/** How long a dug hole, a mound or a hollow stays (world seconds), fading. */
export const MARK_SECONDS = 20 * 60;

export type RecipeMark = {id: string; kind: NonNullable<BlockDef["mark"]>; x: number; y: number; z: number; size: number; from: number; to: number};

/**
 * The marks an animal's recent episodes left (holes, mounds, hollows), still there at a time: pure in its trips, so
 * every viewer, and one who arrives late, sees the same ones. `trips` are its trips of the last `MARK_SECONDS`.
 */
export function marksOf(world: ScheduleWorld, trips: Trip[], epoch: number, kit: ScheduleKit): RecipeMark[] {
    const out: RecipeMark[] = [];
    for (const trip of trips) {
        const owner = (trip as Trip & {owner?: TripOwner | null}).owner;
        if (!owner || trip.end < epoch - MARK_SECONDS) continue;
        const episode = stayEpisode(world, trip, owner, kit);
        if (!episode) continue;
        for (let i = 0; i < episode.keys.length; i++) {
            const key = episode.keys[i];
            if (!key.block.mark || key.t0 > epoch) continue;
            // A burrow's spoil heap and a dust bath's hollow; a turtle's covered pit is a mound.
            const kind = episode.recipe === "dig_burrow" || (episode.recipe === "beach_nest" && i > 2) ? "mound" : key.block.mark;
            out.push({id: `${episode.id}#${i}`, kind, x: key.from.x, y: key.from.y, z: key.from.z, size: Math.max(episode.length * (kind === "hollow" ? 0.9 : 0.5), 0.06), from: key.t0, to: key.t0 + MARK_SECONDS});
        }
    }
    return out;
}

/** For the tests and the review: a stay's episode for a trip (null: none). */
export function episodeOfTrip(world: ScheduleWorld, trip: Trip, kit: ScheduleKit): Episode | null {
    const owner = (trip as Trip & {owner?: TripOwner | null}).owner;
    if (!owner) return null;
    return stayEpisode(world, trip, owner, kit);
}

/** The beat an act reads as (for code that only knows beats). */
export function beatOfAct(act: RecipeAct | null | undefined): ArkBeat | null {
    return act ? BLOCKS[act.block]?.beat ?? null : null;
}
